import com.midtermwork.*;import com.badlogic.gdx.*;import com.badlogic.gdx.graphics.*;import com.badlogic.gdx.backends.lwjgl3.*;
public class RecallBindingsScreenCheck {static float[] pointer={-100,-100};static boolean click,ctrl;static int key=-1;
 public static void main(String[] args){final String dir=args.length>0?args[0]:"../build/recall-key-check";Lwjgl3ApplicationConfiguration c=new Lwjgl3ApplicationConfiguration();c.setTitle("midtermwork - recall and key settings verification");c.setWindowedMode(1152,648);c.setForegroundFPS(60);c.disableAudio(true);
 new Lwjgl3Application(new Main(p->{p[0]=pointer[0];p[1]=pointer[1];}){GameWorld w;SkillBindings binds;Preferences prefs;int frame;
 java.lang.reflect.Field f(String name)throws Exception{java.lang.reflect.Field f=Main.class.getDeclaredField(name);f.setAccessible(true);return f;}
 public void create(){super.create();try{w=(GameWorld)f("world").get(this);w.enemies.clear();w.spikes.clear();w.level=10;w.collectItem(GameWorld.Item.TM);w.chooseTm(GameWorld.Skill.FIRE_PUNCH);w.learnInto(0);w.collectItem(GameWorld.Item.TM);w.chooseTm(GameWorld.Skill.THUNDER_PUNCH);w.learnInto(0);prefs=Gdx.app.getPreferences("midtermwork.controls.ui-check");prefs.clear();prefs.flush();binds=new SkillBindings(prefs);f("bindings").set(this,binds);Input original=Gdx.input;Gdx.input=(Input)java.lang.reflect.Proxy.newProxyInstance(Input.class.getClassLoader(),new Class<?>[]{Input.class},(p,m,a)->{if(m.getName().equals("isKeyJustPressed"))return (Integer)a[0]==key;if(m.getName().equals("isKeyPressed"))return ctrl&&((Integer)a[0]==Input.Keys.CONTROL_LEFT);if(m.getName().equals("isButtonJustPressed")){boolean value=click;click=false;return value;}return m.invoke(original,a);});}catch(Exception ex){throw new RuntimeException(ex);}}
 void point(int index){try{java.util.List<?> buttons=(java.util.List<?>)f("menuButtons").get(this);Object b=buttons.get(index);java.lang.reflect.Field field=b.getClass().getDeclaredField("rect");field.setAccessible(true);ItemHud.RenderedIcon r=(ItemHud.RenderedIcon)field.get(b);pointer[0]=(r.left+r.width/2)*Gdx.graphics.getWidth()/Gdx.graphics.getBackBufferWidth();pointer[1]=(r.top+r.height/2)*Gdx.graphics.getHeight()/Gdx.graphics.getBackBufferHeight();click=true;}catch(Exception ex){throw new RuntimeException(ex);}}
 void capture(String name){Pixmap p=Pixmap.createFromFrameBuffer(0,0,Gdx.graphics.getBackBufferWidth(),Gdx.graphics.getBackBufferHeight());java.io.File file=new java.io.File(dir,name+".png");file.getParentFile().mkdirs();PixmapIO.writePNG(Gdx.files.absolute(file.getAbsolutePath()),p,-1,true);p.dispose();}
 public void render(){frame++;key=-1;ctrl=false;if(frame==5)key=Input.Keys.K;if(frame==14)point(w.recallOptions().indexOf(GameWorld.Skill.FIRE_PUNCH));if(frame==21)point(2);if(frame==25||frame==47)key=Input.Keys.F2;if(frame==32)point(0);if(frame==34){key=Input.Keys.Q;Gdx.input.getInputProcessor().keyDown(key);}if(frame==37)point(3);if(frame==39){key=Input.Keys.R;Gdx.input.getInputProcessor().keyDown(key);}if(frame==50||frame==53)key=Input.Keys.R;if(frame==53)ctrl=true;super.render();if(frame==12)capture("learned-list");if(frame==19)capture("recall-slot");if(frame==22&&(w.skillAt(2)!=GameWorld.Skill.FIRE_PUNCH||w.itemCount(GameWorld.Item.TM)!=0))throw new AssertionError("free recall mouse click");if(frame==45)capture("key-settings");if(frame==51){if(w.level!=10)throw new AssertionError("R skill reset run");SkillBindings reloaded=new SkillBindings(prefs);if(reloaded.key(0)!=Input.Keys.Q||reloaded.key(3)!=Input.Keys.R)throw new AssertionError("saved keys");}if(frame==54){if(w.level!=1)throw new AssertionError("Ctrl+R restart");prefs.clear();prefs.flush();System.out.println("PASS: K recall with actual mouse selection, Q/R key capture, saved preferences, R conflict and Ctrl+R restart");Gdx.app.exit();}}
 },c);}
}
